import sys
from collections import deque

def bfs(start, target, n, matrix):
    queue = deque([(start, 0, [])])
    visited = set()
    visited.add(tuple(sorted(start)))

    while queue:
        current, moves, path = queue.popleft()
        if tuple(sorted(current)) == target:
            return moves, path

        for i in range(3):
            for j in range(n):
                if j + 1 not in current and j + 1 != current[i]:
                    color = matrix[current[i] - 1][j]
                    if color != '*':
                        new_stones = list(current)
                        new_stones[i] = j + 1
                        new_stones.sort()
                        if tuple(new_stones) not in visited:
                            visited.add(tuple(new_stones))
                            queue.append((tuple(new_stones), moves + 1, path + [(current[i], j + 1)]))
    return -1, []

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    stones = tuple(map(int, input[1].split()))
    matrix = [list(line) for line in input[2:]]

    target = (1, 2, 3)
    moves, path = bfs(stones, target, n, matrix)

    if moves == -1:
        print(-1)
    else:
        print(moves)
        for move in path:
            print(move[0], move[1])

main()
